function topoSort(graph) {
 const tasks = new Set();
 const adj = {};
 let hasCycle = false;

 // Collect all tasks and build adjacency list
 for (const [task, deps] of Object.entries(graph)) {
 tasks.add(task);
 if (!adj[task]) adj[task] = new Set();
 for (const d of deps) {
 tasks.add(d);
 if (!adj[d]) adj[d] = new Set();
 if (!adj[task].has(d)) {
 adj[task].add(d);
 }
 }
 }

 // Kahn's algorithm with lexicographic ordering
 const inDegree = {};
 for (const task of tasks) {
 inDegree[task] = 0;
 }

 for (const [task, deps] of Object.entries(adj)) {
 for (const d of deps) {
 inDegree[d] = (inDegree[d] || 0) + 1;
 }
 }

 const queue = [];
 for (const task of tasks) {
 if (!inDegree[task]) {
 queue.push(task);
 }
 }

 // Sort initial queue to ensure lexicographic order when multiple have 0 in-degree
 queue.sort();

 const result = [];

 while (queue.length > 0) {
 // Take the smallest task currently available
 const node = queue.shift();
 result.push(node);

 // Reduce in-degree of neighbors
 for (const neighbor of adj[node] || []) {
 inDegree[neighbor]--;
 if (inDegree[neighbor] === 0) {
 queue.push(neighbor);
 }
 }
 // Sort the queue so the smallest is always at the front
 queue.sort();
 }

 // If there are tasks left, there's a cycle
 if (result.length !== tasks.size) {
 throw new Error("Cycle detected in graph");
 }

 return result;
}

