def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    if text == "":
        raise ValueError("Input cannot be an empty string")

    valid_units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    expected_order = ['d', 'h', 'm', 's']
    prev_order = -1
    total_seconds = 0

    i = 0
    n = len(text)

    while i < n:
        # Check for whitespace
        if text[i] in ' \t\n\r':
            raise ValueError("Input contains whitespace")

        # Parse integer
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Missing number before unit")
        num = int(text[i:j])
        if num < 0:
            raise ValueError("Numbers must be non-negative")

        # Parse unit
        if j >= n or not text[j].isalpha():
            raise ValueError("Missing unit after number")
        unit = text[j]
        if unit not in valid_units:
            raise ValueError(f"Unknown unit: {unit}")

        order = expected_order.index(unit)
        if order <= prev_order:
            raise ValueError(f"Units must be in descending order; {unit} appears after or at same level as previous")
        prev_order = order

        total_seconds += num * valid_units[unit]
        i = j + 1

    if i != n:
        raise ValueError("Trailing characters found")

    return total_seconds
