    except ValueError:
        raise ValueError(f"Invalid end date: {end}")

    if end_date < start_date:
        raise ValueError(f"end ({end}) must not be earlier than start ({start})")

    # Normalize holidays to a set for efficient lookup
    holiday_set = set()
    for h in holidays:
        try:
            holiday_set.add(date.fromisoformat(h))
        except ValueError:
            raise ValueError(f"Invalid holiday date: {h}")

    # Count business days
    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holiday_set:
