 const deps = new Map();

 // Collect all tasks and their dependencies
 for (const [task, before] of Object.entries(graph)) {
 tasks.add(task);
 const uniqueBefore = [...new Set(before)];
 deps.set(task, uniqueBefore);
 }

 // Any task that appears only as a dependency but not as a key
 for (const dep of deps.values()) {
 for (const d of dep) {
 if (!tasks.has(d)) {
 tasks.add(d);
 deps.set(d, []);
 }
 }
 }

 // Kahn's algorithm with lexicographic tie-breaking
 const inDegree = new Map();
 for (const task of tasks) {
 inDegree.set(task, 0);
 }

 for (const [task, before] of deps.entries()) {
 for (const b of before) {
 // b is a prerequisite of task
 inDegree.set(task, inDegree.get(task) + 1);
 }
 }

 // Priority queue: always pick smallest available task
 const available = [];
 for (const task of tasks) {
 if (inDegree.get(task) === 0) {
 available.push(task);
 }
