def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights cannot be negative")
    if sum(weights) == 0:
        raise ValueError("all weights must not be zero")

    w_sum = sum(weights)
    floors = [int((total * w) / w_sum) for w in weights]
    remainder = total - sum(floors)
    if remainder == 0:
        return floors
    fractions = [(total * w) % w_sum for w in weights]
    # Sort indices by fraction descending, then by index ascending
    sorted_indices = sorted(range(len(fractions)), key=lambda i: (-fractions[i], i))
    for i in sorted_indices[:remainder]:
        floors[i] += 1
    return floors
