 for (const task of Object.keys(graph)) {
 tasks.add(task);
 }
 for (const [task, deps] of Object.entries(graph)) {
 // Ensure deps are unique
 const uniqueDeps = new Set(deps);
 for (const dep of uniqueDeps) {
 tasks.add(dep);
 }
 }

 // Initialize inDegree and adjacency lists
 for (const task of tasks) {
 inDegree.set(task, 0);
 adjacency.set(task, []);
 }

 // Build the graph: edges go from dependency -> task
 for (const [task, deps] of Object.entries(graph)) {
 for (const dep of deps) {
 adjacency.set(dep, adjacency.get(dep) || []);
 adjacency.get(dep).push(task);
 inDegree.set(task, inDegree.get(task) + 1);
 }
 }

