function topoSort(graph) {
 const tasks = new Set();
 const inDegree = new Map();
 const adjacency = new Map();

 // Initialize all tasks and their dependencies
 for (const [task, deps] of Object.entries(graph)) {
 tasks.add(task);
 tasks.add(...deps); // Add dependency tasks even if they are not keys
 }

 // Initialize in-degrees and adjacency lists
 for (const task of tasks) {
 if (!inDegree.has(task)) {
 inDegree.set(task, 0);
 adjacency.set(task, []);
 }
 }

 // Build the graph and compute in-degrees
 for (const [task, deps] of Object.entries(graph)) {
 for (const dep of deps) {
 adjacency.get(dep).push(task); // dep -> task (edge from dep to task)
 inDegree.set(task, (inDegree.get(task) || 0) + 1);
 }
 }

 // Kahn's algorithm with lexicographic order
 const queue = [];
 for (const task of tasks) {
 if (inDegree.get(task) === 0) {
 queue.push(task);
 }
 }

 // Sort queue lexicographically
 queue.sort();

 const result = [];
 while (queue.length > 0) {
 const current = queue.shift();
 result.push(current);

 // Decrease in-degree of neighbors
 for (const neighbor of adjacency.get(current) || []) {
 inDegree.set(neighbor, inDegree.get(neighbor) - 1);
 if (inDegree.get(neighbor) === 0) {
 queue.push(neighbor);
 }
 }
 // Sort again to maintain lexicographic order when new zero-degree tasks are added
 queue.sort();
 }

 // Check for cycle: if there are remaining tasks with non-zero in-degree
 if (tasks.size !== result.length) {
 throw new Error('Cycle detected');
 }

 return result;
}

