class LRUCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.cache = {}
        self.order = []  # list of keys in LRU order (oldest first)

    def get(self, key, default=None):
        if key in self.cache:
            # Move key to the end (most recent)
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return default

    def put(self, key, value):
        if key in self.cache:
            # Update value and move to most recent
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used key (first in order)
                lru_key = self.order[0]
                self.cache.pop(lru_key)
                self.order.remove(lru_key)
            self.cache[key] = value
            self.order.append(key)

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache

    def keys(self):
        return list(self.order)
