def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("all weights must not be zero")

    n = len(weights)
    total_weight = sum(weights)

    # Compute floors and remainders
    shares = [total * w // total_weight for w in weights]
    remainders = [(total * w) % total_weight for w in weights]

    # Distribute the remaining cents to those with largest remainders
    leftover = total - sum(shares)
    for _ in range(leftover):
        # Find the index with the maximum remainder (tie-break by lower index)
        max_rem = -1
        max_idx = -1
        for i in range(n):
            if remainders[i] > max_rem:
                max_rem = remainders[i]
                max_idx = i
        shares[max_idx] += 1

    return shares

