function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  let result = '';
  let prevUpper = false;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (/[a-zA-Z0-9]/.test(char)) {
      if (char === char.toUpperCase()) {
        // Uppercase letter
        if (prevUpper && i + 1 < str.length && /[a-z]/.test(str[i + 1])) {
          // Acronym boundary: insert underscore before this uppercase
          result += '_';
        } else if (!prevUpper && /[a-z0-9]/.test(str[i - 1])) {
          // Insert underscore before uppercase if previous was not uppercase
          result += '_';
        }
        prevUpper = true;
      } else {
        // Lowercase or digit
        if (prevUpper) {
          result += '_';
        }
        prevUpper = false;
      }
    } else {
      // Non-alphanumeric character: insert underscore if preceded by upper
      if (prevUpper) {
        result += '_';
      }
      prevUpper = false;
    }

    result += char.toLowerCase();
  }

  return result;
}

