function isValidCardNumber(input) {
 if (typeof input !== 'string') {
 return false;
 }

 const cleaned = input.replace(/[\s-]/g, '');

 // Check length and character validity (only digits after cleaning)
 if (!/^\d+$/.test(cleaned) || cleaned.length < 12 || cleaned.length > 19) {
 return false;
 }

 // Luhn algorithm
 let sum = 0;
 let isDouble = false;

 // Iterate from right to left
 for (let i = cleaned.length - 1; i >= 0; i--) {
 const digit = parseInt(cleaned[i], 10);

 if (isDouble) {
 digit *= 2;
 if (digit > 9) {
 digit -= 9;
 }
 }

 sum += digit;
 isDouble = !isDouble;
 }

 return sum % 10 === 0;
