function topoSort(graph) {
  const tasks = new Set();
  const adj = {}; // adjacency list: for each task, list of tasks it depends on
  const inDegree = {}; // in-degree count for Kahn's algorithm

  // Initialize tasks and dependencies
  for (const [task, deps] of Object.entries(graph)) {
    tasks.add(task);
    adj[task] = [];
    inDegree[task] = 0;

    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      tasks.add(dep);
      adj[dep] = adj[dep] || [];
      adj[task].push(dep); // task depends on dep
      inDegree[task]++;
    }
  }

  // Ensure all tasks have entries
  for (const task of tasks) {
    if (!adj[task]) adj[task] = [];
    if (!inDegree[task]) inDegree[task] = 0;
  }

  // Initialize queue with tasks having zero in-degree
  const queue = [];
  for (const task of tasks) {
    if (inDegree[task] === 0) {
      queue.push(task);
    }
  }

  // Sort queue by task name (smallest first)
  queue.sort();

  const result = [];
  while (queue.length > 0) {
    const task = queue.shift();
    result.push(task);

    // For each task that depends on the current task, reduce its in-degree
    for (const dependent of adj[task]) {
      inDegree[dependent]--;
      if (inDegree[dependent] === 0) {
        queue.push(dependent);
      }
    }

    // Sort queue again to maintain smallest-first order
    queue.sort();
  }

  // Check for cycles: if result length is less than number of tasks
  if (result.length !== tasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

