class LRUCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._store = {}
        self._order = []  # list of keys ordered from LRU to MRU

    def _move_to_end(self, key):
        """Move a key to the end (most recently used) and update internal structures."""
        if key in self._store:
            # Remove from current position
            self._order.remove(key)
            self._store.pop(key)
            # Re-add at end
            self._store[key] = self._store[key]
            self._order.append(key)
        else:
            # New key
            self._store[key] = None
            self._order.append(key)

    def get(self, key, default=None):
        if key in self._store:
            self._move_to_end(key)
            return self._store[key]
        return default

    def put(self, key, value):
        if key in self._store:
            self._move_to_end(key)
            self._store[key] = value
        else:
            if len(self._store) >= self._capacity:
                # Remove least recently used key (first in _order)
                lru_key = self._order[0]
                self._order.pop(0)
                del self._store[lru_key]
            self._store[key] = value
            self._order.append(key)

    def __len__(self):
        return len(self._store)

    def __contains__(self, key):
        return key in self._store

    def keys(self):
        return list(self._order)
