 tasks.add(task);
 deps.forEach(d => tasks.add(d));
 dependencies.set(task, [...new Set(deps)]); // deduplicate
 }

 // Initialize in-degree for all tasks
 for (const task of tasks) {
 inDegree.set(task, 0);
 }

 // Calculate in-degrees based on dependencies
 for (const [task, deps] of dependencies) {
 for (const dep of deps) {
 // dep -> task
 inDegree.set(task, (inDegree.get(task) || 0) + 1);
