 result.push(current);

 // Reduce in-degree of tasks that depend on current
 for (const [task, deps] of dependencies) {
 if (deps.includes(current)) {
 inDegree.set(task, inDegree.get(task) - 1);
 if (inDegree.get(task) === 0) {
 available.push(task);
 }
 }
 }

 // Maintain sorted order of available tasks
 available.sort();
 }

 if (result.length !== tasks.size) {
 throw new Error('cycle detected');
 }

 return result;
}

