from datetime import date, timedelta

def business_days(start, end, holidays=()):
    # Validate and parse start and end dates
    try:
        start_date = date.fromisoformat(start)
        end_date = date.fromisoformat(end)
    except ValueError:
        raise ValueError("Invalid date string format (expected YYYY-MM-DD)")

    if end_date < start_date:
        raise ValueError("end must be later than or equal to start")

    # Convert holidays to a set for O(1) lookup, filtering out invalid/out-of-range duplicates implicitly
    holiday_set = set()
    for h in holidays:
        try:
            h_date = date.fromisoformat(h)
            holiday_set.add(h_date)
        except ValueError:
            raise ValueError(f"Invalid holiday date: {h}")

    count = 0
    current = start_date
    while current < end_date:
        # Check if current day is Monday (0) to Friday (5)
        if current.weekday() < 5:
            if current not in holiday_set:
                count += 1
        current += timedelta(days=1)

    return count
