def business_days(start, end, holidays=()):
    # Validate start and end
    try:
        start_date = datetime.strptime(start, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid start date string: '{start}'")

    try:
        end_date = datetime.strptime(end, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid end date string: '{end}'")

    if end_date < start_date:
        raise ValueError("end must not be earlier than start")

    # Normalize holidays: remove duplicates and convert to set of date objects
    holiday_set = set()
    for h in holidays:
        try:
            holiday_date = datetime.strptime(h, "%Y-%m-%d").date()
            holiday_set.add(holiday_date)
        except ValueError:
            raise ValueError(f"Invalid holiday date string: '{h}'")

    # Count business days
    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += timedelta(days=1)

    return count
