def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("all weights must not be zero")

    total_weight = sum(weights)
    base = [w // total_weight for w in weights]
    remainders = [w % total_weight for w in weights]

    leftover = total - sum(base)
    if leftover > 0:
        # Find indices with largest remainders, descending, then ascending index
        sorted_indices = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
        for i in sorted_indices[:leftover]:
            base[i] += 1

    return base
