    this._listeners = new Map();
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    this._listeners.get(event).push(fn);
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    this.on(event, fn);
    // Tag the listener as 'once' by storing a wrapper that removes itself
    const onceWrapper = (...args) => {
      this.off(event, onceWrapper);
      fn.apply(this, args);
    };
    this._listeners.get(event).push(onceWrapper);
    return this;
  }

  off(event, fn) {
    if (!this._listeners.has(event)) return this;
    const listeners = this._listeners.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
    return this;
  }

  emit(event, ...args) {
    if (!this._listeners.has(event)) return false;
    const listeners = this._listeners.get(event);
    let called = false;
    const activeListeners = [...listeners]; // snapshot
    for (const listener of activeListeners) {
      try {
        listener.apply(this, args);
        called = true;
      } catch (e) {
        // Errors during listener execution do not affect the list
      }
    }
    return called;
  }

  listenerCount(event) {
    return this._listeners.has(event) ? this._listeners.get(event).length : 0;
  }
}

