                if not part:
                    raise ValueError(f"Empty identifier in prerelease: {s}")
                # Check for leading zeros in all-digit identifiers
                if part.isdigit() and len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Leading zeros in all-digit prerelease identifier: {s}")

