def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Check for digit characters
    if any(ch.isdigit() for ch in s):
        raise ValueError("Input must not contain digit characters")

    if not s:
        return ""

    result = []
    count = 1
    prev = s[0]

    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            prev = ch
            count = 1

    result.append(f"{count}{prev}")
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Extract count
        start = i
        while i < n and s[i].isdigit():
            i += 1

        if i == start:
            raise ValueError("Missing count")

        count = int(s[start:i])
        if count == 0:
            raise ValueError("Count must be at least 1 (leading zeros allowed)")

        # Extract character
        if i >= n:
            raise ValueError("Trailing digits with no character")

        ch = s[i]
        if ch.isdigit():
            raise ValueError("Character must be non-digit")

        i += 1

        result.append(ch * count)

    return "".join(result)
