def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote: literal quote character
                        field_chars.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Reached end of string without closing quote
                raise ValueError("Quoted field not closed")

            if i >= n or line[i] != ',':
                raise ValueError("After closing quote must be a comma or end of line")
            fields.append(''.join(field_chars))
            i += 1
        elif line[i] == ',':
            fields.append('')
            i += 1
        else:
            # Unquoted field: read until comma or end
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1
            else:
                break

    return fields
