def compare_versions(a, b):
    # Validate and parse version strings
    def parse_version(s):
        # Pattern: MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        pattern = r'^(\d+)(\.\d+)(\.\d+)(?:-([0-9A-Za-z-]+))?(?:\+([0-9A-Za-z-]+))?$'
        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version string: {s}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease = match.group(4)
        build = match.group(5)

        # Validate prerelease identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            for pid in prerelease_ids:
                if not pid:
                    raise ValueError(f"Empty prerelease identifier in {s}")
                # Check for leading zeros in numeric identifiers
                if pid.isdigit() and (pid[0] == '0' and len(pid) > 1):
                    raise ValueError(f"Leading zeros in prerelease identifier: {pid}")

        # Validate build identifiers
        if build:
            build_ids = build.split('.')
            for bid in build_ids:
                if not bid:
                    raise ValueError(f"Empty build identifier in {s}")

        return (major, minor, patch, prerelease, build)

    try:
        v1 = parse_version(a)
    except ValueError:
        raise ValueError(f"Invalid version string: {a}")

    try:
        v2 = parse_version(b)
    except ValueError:
        raise ValueError(f"Invalid version string: {b}")

    # Compare major, minor, patch
    if v1[0] != v2[0]:
        return -1 if v1[0] < v2[0] else 1
    if v1[1] != v2[1]:
        return -1 if v1[1] < v2[1] else 1
    if v1[2] != v2[2]:
        return -1 if v1[2] < v2[2] else 1

    # Compare prerelease
    has_prerelease_1 = v1[3] is not None
    has_prerelease_2 = v2[3] is not None

    if has_prerelease_1 and not has_prerelease_2:
        return -1
    if not has_prerelease_1 and has_prerelease_2:
        return 1

    # Both have prerelease or both don't
    prerelease1 = v1[3]
    prerelease2 = v2[3]

    ids1 = prerelease1.split('.')
    ids2 = prerelease2.split('.')

    min_len = min(len(ids1), len(ids2))

    for i in range(min_len):
        id1 = ids1[i]
        id2 = ids2[i]

        id1_is_digit = id1.isdigit()
        id2_is_digit = id2.isdigit()

        # All-digit identifiers have lower precedence than alphanumeric
        if id1_is_digit and not id2_is_digit:
            return -1
        if not id1_is_digit and id2_is_digit:
            return 1

        # Both digit or both non-digit: compare numerically or lexicographically
        if id1_is_digit and id2_is_digit:
            num1 = int(id1)
            num2 = int(id2)
            if num1 != num2:
                return -1 if num1 < num2 else 1
        else:
            if id1 != id2:
                return -1 if id1 < id2 else 1

    # If we've compared all shared identifiers and they are equal
    if len(ids1) < len(ids2):
        return -1
    elif len(ids1) > len(ids2):
        return 1

    return 0
