  let value = n;
  let unitIndex = 0;

  // Divide by 1024 until value is < 1024 or we hit TB
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Format with at most one decimal place, dropping trailing .0
  const formattedValue = value < 1024 ? value.toFixed(1).replace(/\.0$/, '') : value.toFixed(1).replace(/\.0$/, '');
  return `${formattedValue} ${units[unitIndex]}`;
}

