def compare_versions(a, b):
    # Regex to validate and parse a version string
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'

    match_a = re.match(pattern, a)
    if not match_a:
        raise ValueError(f"Invalid version string: {a}")

    match_b = re.match(pattern, b)
    if not match_b:
        raise ValueError(f"Invalid version string: {b}")

    major_a, minor_a, patch_a = int(match_a.group(1)), int(match_a.group(2)), int(match_a.group(3))
    major_b, minor_b, patch_b = int(match_b.group(1)), int(match_b.group(2)), int(match_b.group(3))

    prerelease_a = match_a.group(4)
    prerelease_b = match_b.group(4)

    # Compare major, minor, patch
    if major_a < major_b:
        return -1
    elif major_a > major_b:
        return 1

    if minor_a < minor_b:
        return -1
    elif minor_a > minor_b:
        return 1

    if patch_a < patch_b:
        return -1
    elif patch_a > patch_b:
        return 1

    # If no prerelease, it has higher precedence than one with a prerelease
    if prerelease_a is None and prerelease_b is not None:
        return 1
    if prerelease_a is not None and prerelease_b is None:
        return -1

    # Compare prerelease
    parts_a = prerelease_a.split('.')
    parts_b = prerelease_b.split('.')

    # If one has fewer parts, it's shorter
    if len(parts_a) < len(parts_b):
        return -1
    if len(parts_a) > len(parts_b):
        return 1

    for part_a, part_b in zip(parts_a, parts_b):
        # Check if part is all digits
        is_digit_a = part_a.isdigit()
        is_digit_b = part_b.isdigit()

        if is_digit_a and is_digit_b:
            # Compare numerically
            if int(part_a) < int(part_b):
                return -1
            elif int(part_a) > int(part_b):
                return 1
        elif is_digit_a:
            # All-digit identifier has lower precedence than alphanumeric
            return -1
        elif is_digit_b:
            return 1
        else:
            # Compare lexically
            if part_a < part_b:
                return -1
            elif part_a > part_b:
                return 1

    # If all shared parts are equal, the shorter prerelease is lower
    # But we already checked lengths, so they must be equal
    return 0

