function formatBytes(n) {
  if (!Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;

  for (let i = 0; i < units.length; i++) {
    if (value < 1024) {
      break;
    }
    value /= 1024;
  }

  // Round to one decimal place, but handle the edge case where rounding makes it exactly 1024
  // and we should move up one unit instead.
  let rounded = Math.round(value * 10) / 10;
  if (rounded === 1024 && i < units.length - 1) {
    rounded = 1024 / 1024; // effectively move up one unit
    i++;
  }

  // Format the number: if it's an integer, don't show ".0"
  const str = rounded % 1 === 0 ? rounded.toString() : rounded.toFixed(1);
  return `${str} ${units[i]}`;
}

module.exports = { formatBytes };
