def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Loop completed without breaking -> unclosed quote
                raise ValueError("Unclosed quoted field")

            if i >= n:
                raise ValueError("Unclosed quoted field")

            fields.append(''.join(field_chars))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            i += 1 # skip the comma

    return fields
