        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain digit characters")
    if not s:
        return ""
    encoded = []
    prev = s[0]
    count = 1
    for char in s[1:]:
        if char != prev:
            encoded.append(f"{count}{prev}")
            prev = char
            count = 1
        else:
            count += 1
    encoded.append(f"{count}{prev}")
    return "".join(encoded)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    decoded = []
    i = 0
    n = len(s)
    while i < n:
        # Extract count
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Missing count")
        count_str = s[i:j]
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        # Extract character
        if j >= n:
            raise ValueError("Trailing digits with no character")
        char = s[j]
        if char.isdigit():
            raise ValueError("Character must be non-digit")
        decoded.append(char * count)
        i = j + 1
    return "".join(decoded)
