    }

    if (trimmed.includes('-')) {
      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part: missing start or end in range');
      }
      const lo = Number(loStr);
      const hi = Number(hiStr);
      if (Number.isNaN(lo) || Number.isNaN(hi)) {
        throw new SyntaxError('malformed part: not a valid number');
      }
      if (lo > hi) {
        throw new RangeError('range start greater than end');
      }
      for (let i = lo; i <= hi; i++) {
        numbers.add(i);
