def compare_versions(a, b):
    """
    Compare two Semantic Versioning 2.0.0 strings.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    Raises ValueError if the strings are invalid.
    """
    # Regex pattern for valid semver 2.0.0
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-(.+))?(?:\+.+)?$'

    # Validate and parse both versions
    match_a = re.match(pattern, a)
    if not match_a:
        raise ValueError(f"Invalid version string: {a}")

    match_b = re.match(pattern, b)
    if not match_b:
        raise ValueError(f"Invalid version string: {b}")

    major_a, minor_a, patch_a = int(match_a.group(1)), int(match_a.group(2)), int(match_a.group(3))
    prerelease_a = match_a.group(4)

    major_b, minor_b, patch_b = int(match_b.group(1)), int(match_b.group(2)), int(match_b.group(3))
    prerelease_b = match_b.group(4)

    # Compare major, minor, patch
    if major_a != major_b:
        return (major_a > major_b) - (major_a < major_b)
    if minor_a != minor_b:
        return (minor_a > minor_b) - (minor_a < minor_b)
    if patch_a != patch_b:
        return (patch_a > patch_b) - (patch_a < patch_b)

    # Compare prerelease
    if prerelease_a is None and prerelease_b is None:
        return 0
    if prerelease_a is None:
        return 1  # No prerelease has higher precedence
    if prerelease_b is None:
        return -1  # No prerelease has higher precedence

    # Parse prerelease identifiers
    ids_a = prerelease_a.split('.')
