function expandRanges(spec) {
 if (typeof spec !== 'string') {
 throw new TypeError('spec must be a string');
 }

 const parts = spec.split(',').map(p => p.trim());

 const values = new Set();

 for (const part of parts) {
 if (part === '') continue; // leading/trailing comma handled by split

 const [lo, hi] = part.split('-');

 if (lo === undefined || hi === undefined) {
 if (lo === undefined && hi === undefined) {
 throw new SyntaxError('empty part');
 } else if (lo === undefined) {
 // "1-"
 throw new SyntaxError('missing end');
 } else {
 throw new SyntaxError('missing start');
 }
 }

 const start = parseInt(lo, 10);
 const end = parseInt(hi, 10);

 if (isNaN(start) || isNaN(end)) {
 throw new SyntaxError('non-numeric part');
 }

 if (!Number.isInteger(start) || !Number.isInteger(end)) {
 throw new SyntaxError('non-integer part');
 }

 if (start < 0 || end < 0) {
 throw new SyntaxError('negative numbers not allowed');
 }

 if (start > end) {
 throw new RangeError('range start greater than end');
 }

 for (let i = start; i <= end; i++) {
 values.add(i);
 }
 }

 return Array.from(values).sort((a, b) => a - b);
}

module.exports = { expandRanges };
