function formatBytes(n) {
    if (typeof n !== 'number' || !Number.isFinite(n)) {
        throw new TypeError('n must be a finite number');
    }
    if (!Number.isInteger(n) || n < 0) {
        throw new RangeError('n must be a non-negative integer');
    }

    const units = ['B', 'KB', 'MB', 'GB', 'TB'];
    let value = n;
    let unitIndex = 0;

    // Handle zero case
    if (value === 0) {
        return '0 B';
    }

    // Iterate through units until value < 1024 or we hit TB
    while (value >= 1024 && unitIndex < units.length - 1) {
        value /= 1024;
        unitIndex++;
    }

    // Round to at most one decimal place
    if (value >= 100) {
        value = Math.round(value * 10) / 10;
    } else {
        value = Math.round(value * 100) / 100;
    }

    // If rounding made it exactly 1024, move to next unit (except for TB)
    if (value === 1024 && unitIndex < units.length - 1) {
        value = value / 1024;
        unitIndex++;
    }

    // Format the output: remove trailing .0
    const formattedValue = value.toString();
    const hasDecimal = formattedValue.includes('.');
    if (hasDecimal && formattedValue.endsWith('0')) {
        return value.toFixed(1).replace('.0', '') + ' ' + units[unitIndex];
    } else {
        return value.toFixed(1) + ' ' + units[unitIndex];
    }
}

module.exports = { formatBytes };
