function formatBytes(n) {
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < 0) {
    if (!Number.isFinite(n)) {
      throw new TypeError("n must be a finite number");
    }
    throw new RangeError("n must be a non-negative integer");
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let unitIndex = 0;
  let value = n;

  // Find the appropriate unit
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  let rounded = Math.round(value * 10) / 10;

  // If rounding turned the value into 1024 and a larger unit exists, move up
  while (rounded === 1024 && unitIndex < units.length - 1) {
    rounded /= 1024;
    unitIndex++;
  }

  // Leave out the decimal if it's .0
  const displayValue = rounded === Math.round(rounded) ? String(Math.round(rounded)) : rounded.toFixed(1);

  return `${displayValue} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
