class Emitter {
  constructor() {
    this._events = new Map();
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._events.has(event)) {
      this._events.set(event, new Set());
    }
    this._events.get(event).add(fn);
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._events.has(event)) {
      this._events.set(event, new Set());
    }
    this._events.get(event).add(fn);
    // Mark as once by storing a wrapper that removes itself after firing
    const onceFn = (...args) => {
      const listeners = this._events.get(event);
      if (listeners && listeners.has(fn)) {
        listeners.delete(fn);
        fn.apply(this, args);
      }
    };
    this._events.get(event).add(onceFn);
    return this;
  }

  off(event, fn) {
    if (!this._events.has(event)) {
      return this;
    }
    const listeners = this._events.get(event);
    if (listeners.has(fn)) {
      listeners.delete(fn);
    }
    if (listeners.size === 0) {
      this._events.delete(event);
    }
    return this;
  }

  emit(event, ...args) {
    if (!this._events.has(event)) {
      return false;
    }
    const listeners = Array.from(this._events.get(event));
    let called = false;
    for (const fn of listeners) {
      try {
        fn.apply(this, args);
        called = true;
      } catch (e) {
        // Continue despite errors in listeners
      }
    }
    return called;
  }

  listenerCount(event) {
    if (!this._events.has(event)) {
      return 0;
    }
    return this._events.get(event).size;
  }
}

module.exports = { Emitter };
