function expandRanges(spec) {
 if (typeof spec !== 'string') {
 throw new TypeError('spec must be a string');
 }

 const parts = spec.split(',').map(p => p.trim());
 const result = new Set();

 for (const part of parts) {
 if (part === '') {
 continue;
 }

 // Check format: either a single number or "lo-hi"
 const match = part.match(/^(\d+)-(\d+)$|^(\d+)$/);
 if (!match) {
 throw new SyntaxError('Malformed part: ' + part);
 }

 const [, lo1, hi1] = match;
 const lo = parseInt(lo1, 10);
 const hi = parseInt(hi1, 10);

 if (lo < 0 || hi < 0) {
 throw new SyntaxError('Negative number in part: ' + part);
 }

 if (lo > hi) {
 throw new RangeError('Range start ' + lo + ' is greater than end ' + hi);
 }

 if (hi === lo) {
 result.add(lo);
 } else {
 for (let i = lo; i <= hi; i++) {
 result.add(i);
 }
 }
 }

 const sorted = Array.from(result).sort((a, b) => a - b);
 return sorted;
}

module.exports = { expandRanges };
