  let rounded = Math.round(value * 10) / 10;

  // If rounding caused the value to reach 1024 and there's a larger unit, move up
  if (rounded === 1024 && i < units.length - 1) {
    rounded /= 1024;
    i++;
  }

  const unit = units[i];
  // Leave out the decimal if it is .0
  if (rounded % 1 === 0) {
