def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input string must not contain digit characters")
    if not s:
        return ""
    result = []
    prev = None
    count = 0
    for char in s:
        if char == prev:
            count += 1
        else:
            if prev is not None:
                result.append(f"{count}{prev}")
            prev = char
            count = 1
    if prev is not None:
        result.append(f"{count}{prev}")
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    i = 0
    result = []
    while i < len(s):
        # Extract count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Missing count")
        count_str = s[i:j]
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        char = s[j]
        if not char.isalpha(): # Only non-digits allowed, but we already ensured count is digits
            if char.isdigit():
                raise ValueError("Trailing digits with no character")
        i = j + 1
        if i > len(s):
            break
        result.append(char * count)
    if i != len(s):
        raise ValueError("Trailing digits with no character")
    return "".join(result)
