class Emitter {
  constructor() {
    this._listeners = new Map(); // Map[event, Set[fn]]
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._listeners.has(event)) {
      this._listeners.set(event, new Set());
    }
    this._listeners.get(event).add(fn);
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    this.on(event, fn);
    const fnWrapper = (args) => {
      fn.apply(this, args);
      this.off(event, fn);
    };
    this._listeners.get(event).add(fnWrapper);
    return this;
  }

  off(event, fn) {
    if (this._listeners.has(event)) {
      const set = this._listeners.get(event);
      set.delete(fn);
    }
    return this;
  }

  emit(event, ...args) {
    let calledAtLeastOne = false;
    if (this._listeners.has(event)) {
      const listeners = this._listeners.get(event);
      // Create a snapshot of the listeners to avoid issues with modifications during iteration
      const listenerList = Array.from(listeners);
      for (const fn of listenerList) {
        if (fn.apply(this, args)) {
          calledAtLeastOne = true;
        }
      }
    }
    return calledAtLeastOne;
  }

  listenerCount(event) {
    if (this._listeners.has(event)) {
      return this._listeners.get(event).size;
    }
    return 0;
  }
}

