function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      continue;
    }

    if (trimmed.includes('-')) {
      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part: missing start or end');
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError('malformed part: non-numeric start or end');
      }
      if (lo < 0 || hi < 0) {
        throw new SyntaxError('malformed part: negative numbers not allowed');
      }
      if (lo > hi) {
        throw new RangeError(`range start ${lo} is greater than end ${hi}`);
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      const num = parseInt(trimmed, 10);
      if (isNaN(num)) {
        throw new SyntaxError('malformed part: non-numeric value');
      }
      if (num < 0) {
        throw new SyntaxError('malformed part: negative number');
      }
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

