def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            result.append("")
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    i += 1
            else:
                # Loop finished without breaking -> unclosed quote
                raise ValueError("unclosed quoted field")
        elif line[i] == ',':
            # Unquoted field ended
            i += 1
        else:
            # Regular character in unquoted field
            i += 1

    result.append("")
    return result
