def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    for ch in s:
        if ch.isdigit():
            raise ValueError("Input must not contain digit characters")

    if not s:
        return ""

    encoded = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 1
        while i + count < len(s) and s[i + count] == char:
            count += 1
        encoded.append(str(count) + char)
        i += count
    return "".join(encoded)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    decoded = []
    i = 0
    while i < len(s):
        if i >= len(s):
            break

        # Parse count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        if j == i: # No digits found
            raise ValueError("Missing count")

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count must be at least 1")

        if j >= len(s): # Digits at the end with no character
            raise ValueError("Trailing digits with no character")

        char = s[j]

        decoded.append(char * count)
        i = j + 1

    return "".join(decoded)
