    if not isinstance(text, str):
        raise TypeError("Input must be a string")

    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    # Split into time part and suffix
    parts = text.split()
    if len(parts) == 0:
        raise ValueError("Empty input")

    time_part = parts[0]
    suffix = parts[1] if len(parts) > 1 else None

    if not time_part or not suffix:
        raise ValueError("Missing AM/PM")

    # Validate time part format: H:MM or HH:MM
    if len(time_part) < 4 or time_part[-2] != ':':
        raise ValueError("Invalid time format")

    hour_str = time_part[:time_part.index(':')]
    minute_str = time_part[time_part.index(':')+1:]

    if not (1 <= len(hour_str) <= 2 and 2 == len(minute_str)):
        raise ValueError("Invalid hour or minute length")

    # Validate hour value
    hour = int(hour_str)
    if hour < 1 or hour > 12:
        raise ValueError("Hour must be between 1 and 12")

    # Validate minute value
    minute = int(minute_str)
    if minute < 0 or minute > 59:
        raise ValueError("Minutes must be between 00 and 59")

    # Validate suffix
    if not suffix.isalpha() or len(suffix) != 2:
        raise ValueError("Invalid suffix")

    suffix_upper = suffix.upper()
    if suffix_upper not in ('AM', 'PM'):
        raise ValueError("Suffix must be AM or PM")

    # Convert to 24h format
    if suffix_upper == 'PM':
        hour = (hour % 12) + 12
    elif suffix_upper == 'AM':
        if hour == 12:
            hour = 0

    return f"{hour:02d}:{minute:02d}"
