function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  if (rows.length !== 0 && !rows.every(row => Array.isArray(row))) {
    throw new TypeError('rows must be an array of arrays');
  }

  // Convert each cell: null/undefined -> empty string
  const converted = rows.map(row => row.map(cell => {
    if (cell === null || cell === undefined) return '';
    return String(cell);
  }));

  // Find the maximum column width
  const maxColWidth = Math.max(0, ...converted.map(row => row.length));

  // Build lines
  const lines = [];
  for (const row of converted) {
    // Pad missing cells with empty strings
    const paddedRow = [...row];
    while (paddedRow.length < maxColWidth) {
      paddedRow.push('');
    }

    const parts = paddedRow.map(cell => {
      const len = cell.length;
      if (len >= maxColWidth) {
        return cell;
      }
      return cell + ' '.repeat(maxColWidth - len);
    });

    const line = parts.join(' | ');
    lines.push(line);
  }

  return lines.join('\n');
}

module.exports = { formatTable };
