def is_balanced(code):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    i = 0
    n = len(code)
    while i < n:
        ch = code[i]
        if ch == '"':
            # Skip the entire string literal, handling escaped quotes and backslashes
            i += 1
            while i < n:
                if code[i] == '\\':
                    i += 2 # Skip escaped character
                elif code[i] == '"':
                    i += 1 # End of string literal
                    break
                else:
                    i += 1
        elif ch in bracket_map:
            if not stack or stack[-1] != bracket_map[ch]:
                return False
            stack.pop()
        elif ch in '([{':
            stack.append(ch)
        i += 1
    return not stack
