function retry(fn, attempts) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    return Promise.reject(new RangeError('attempts must be a positive integer'));
  }
  if (typeof fn !== 'function') {
    return Promise.reject(new TypeError('fn must be a function'));
  }

  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      let result = fn(attempt);
      if (result instanceof Promise) {
        return result.then(
          (value) => value, // success, resolve with the value
          (err) => { // rejection, continue to next attempt
            lastError = err;
            if (attempt === attempts) {
              return Promise.reject(lastError);
            }
            return retry(fn, attempts); // recursive retry
          }
        );
      } else {
        // fn returned a non-promise value synchronously
        return result; // success, resolve immediately
      }
    } catch (err) {
      // fn threw synchronously
      lastError = err;
      if (attempt === attempts) {
        return Promise.reject(lastError);
      }
      // continue to next attempt
    }
  }
}

module.exports = { retry };
