    throw new RangeError("Invalid date format");
  }

  const birthDate = new Date(birth);
  const onDate = new Date(on);

  if (onDate < birthDate) {
    throw new RangeError("on must be on or after birth");
  }

  const yearDiff = onDate.getFullYear() - birthDate.getFullYear();
  const monthDiff = onDate.getMonth() - birthDate.getMonth();
  const dayDiff = onDate.getDate() - birthDate.getDate();

