  if (typeof attempts !== 'number' || !Number.isInteger(attempts) || attempts < 1) {
    return Promise.reject(new RangeError('attempts must be an integer of at least 1'));
  }
  if (typeof fn !== 'function') {
    return Promise.reject(new TypeError('fn must be a function'));
  }

  let attemptNumber = 1;

  function attempt() {
    if (attemptNumber > attempts) {
      return Promise.reject(new RangeError('max attempts exceeded'));
    }

    let result;
    try {
      result = fn(attemptNumber);
    } catch (err) {
      if (attemptNumber < attempts) {
        attemptNumber++;
        return attempt();
      }
      return Promise.reject(err);
    }

    // If fn returned a promise, await it
    if (result && typeof result.then === 'function') {
      return result.catch(err => {
        if (attemptNumber < attempts) {
          attemptNumber++;
          return attempt();
        }
        return Promise.reject(err);
      });
    }

    // Success
    return result;
  }

  return attempt();
}

