function isValidDate(str) {
  const regex = /^(\d{4})-(\d{0,2})-(\d{0,2})$/;
  const match = str.match(regex);
  if (!match) return false;
  const [, year, month, day] = match;
  const parsed = new Date(`${year}-${month}-${day}`);
  return parsed.getFullYear() === parseInt(year, 10) &&
         parsed.getMonth() === parseInt(month, 10) - 1 &&
         parsed.getDate() === parseInt(day, 10);
}

function ageOn(birth, on) {
  if (!isValidDate(birth) || !isValidDate(on)) {
    throw new RangeError("Invalid date format. Expected YYYY-MM-DD");
  }

  const birthDate = new Date(birth);
  const onDate = new Date(on);

  if (onDate < birthDate) {
    throw new RangeError("on must be on or after birth");
  }

  let age = onDate.getFullYear() - birthDate.getFullYear();

  // Check if the birthday has occurred this year
  const month = birthDate.getMonth();
  const day = birthDate.getDate();

  // For Feb 29, in non-leap years, birthday is Mar 1
  if (month === 1 && day === 29) {
    // Check if the current year is a leap year
    const currentYear = onDate.getFullYear();
    const isLeap = (currentYear % 4 === 0 && (currentYear % 100 !== 0 || currentYear % 400 === 0));
    if (!isLeap) {
      // Birthday is on Mar 1, so check if current month >= 2 or (current month === 1 and current day >= 1)
      if (onDate.getMonth() < 2 || (onDate.getMonth() === 1 && onDate.getDate() < 1)) {
        age -= 1;
      }
    }
  } else {
    // Normal birthday check
    if (onDate.getMonth() < month || (onDate.getMonth() === month && onDate.getDate() < day)) {
      age -= 1;
    }
  }

  return age;
}

module.exports = { ageOn };
