                raise ValueError("Invalid character in grid")
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS to find shortest path
    queue = [(0, start[0], start[1])] # (moves, row, col)
    visited = set()
    visited.add(start)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        moves, r, c = queue.pop(0)
        if (r, c) == end:
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((moves + 1, nr, nc))

